package catalog

import (
	"context"

	"github.com/tanvoxyz/tanvo/libs/core"
)

// TaxFilter narrows [TaxRepository.List].
type TaxFilter struct {
	// AutoGenerated, when set, keeps only taxes whose AutoGenerated flag
	// equals it.
	AutoGenerated *bool
}

// TaxRepository stores taxes. Every method is scoped to an organization.
type TaxRepository interface {
	// Create inserts t; a code already used in the organization fails with
	// core.ErrConflict.
	Create(ctx context.Context, t *Tax) error
	// Update replaces the stored tax t.ID with t (same uniqueness rule).
	Update(ctx context.Context, t *Tax) error
	// Delete removes the tax id. Callers detach it from every owner first;
	// issued documents keep their applied-tax snapshots (domain §7.7).
	Delete(ctx context.Context, org core.OrganizationID, id core.TaxID) error
	// Get returns the tax id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.TaxID) (*Tax, error)
	// GetByCode returns the tax with that code, or core.ErrNotFound. It
	// also finds the auto-generated EU taxes by their codes (domain
	// §22.10).
	GetByCode(ctx context.Context, org core.OrganizationID, code string) (*Tax, error)
	// ListByCodes returns the taxes with the given codes, in the order of
	// codes; a missing code fails with core.ErrNotFound.
	ListByCodes(ctx context.Context, org core.OrganizationID, codes []string) ([]*Tax, error)
	// ListByIDs returns the taxes with the given IDs, in the order of ids;
	// a missing ID fails with core.ErrNotFound.
	ListByIDs(ctx context.Context, org core.OrganizationID, ids []core.TaxID) ([]*Tax, error)
	// List returns the organization's taxes in creation order.
	List(ctx context.Context, org core.OrganizationID, f TaxFilter, page core.PageRequest) (core.Page[*Tax], error)
}

// CommitmentRepository stores plan commitments. Every method is scoped to
// an organization.
type CommitmentRepository interface {
	// Create inserts c; a second commitment of the same type on the plan
	// fails with core.ErrConflict.
	Create(ctx context.Context, c *Commitment) error
	// Update replaces the stored commitment c.ID with c.
	Update(ctx context.Context, c *Commitment) error
	// Delete removes the commitment id.
	Delete(ctx context.Context, org core.OrganizationID, id core.CommitmentID) error
	// Get returns the commitment id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.CommitmentID) (*Commitment, error)
	// GetByPlan returns the plan's commitment of type t, or
	// core.ErrNotFound.
	GetByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID, t CommitmentType) (*Commitment, error)
	// ListByPlan returns the plan's commitments in creation order.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*Commitment, error)
}

// UsageThresholdRepository stores the usage thresholds of plans and
// subscriptions. Every method is scoped to an organization.
type UsageThresholdRepository interface {
	// Create inserts u; a second recurring threshold, or a non-recurring
	// amount already used, for the same owner fails with core.ErrConflict.
	Create(ctx context.Context, u *UsageThreshold) error
	// Update replaces the stored threshold u.ID with u (same rules).
	Update(ctx context.Context, u *UsageThreshold) error
	// Delete removes the threshold id.
	Delete(ctx context.Context, org core.OrganizationID, id core.UsageThresholdID) error
	// Get returns the threshold id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.UsageThresholdID) (*UsageThreshold, error)
	// ListByPlan returns the plan's thresholds by ascending amount, the
	// recurring one last.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*UsageThreshold, error)
	// ListBySubscription returns the subscription's own thresholds by
	// ascending amount, the recurring one last.
	ListBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*UsageThreshold, error)
}

// FeatureRepository stores features with their privileges, as one
// aggregate. Every method is scoped to an organization.
type FeatureRepository interface {
	// Create inserts f and its privileges; a code already used in the
	// organization, or a privilege code repeated in the feature, fails with
	// core.ErrConflict.
	Create(ctx context.Context, f *Feature) error
	// Update replaces the stored feature f.ID and its privileges with f.
	Update(ctx context.Context, f *Feature) error
	// Delete removes the feature id and its privileges; callers remove its
	// entitlements in the same transaction (domain §7.10).
	Delete(ctx context.Context, org core.OrganizationID, id core.FeatureID) error
	// Get returns the feature id with its privileges, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.FeatureID) (*Feature, error)
	// GetByCode returns the feature with that code, or core.ErrNotFound.
	GetByCode(ctx context.Context, org core.OrganizationID, code string) (*Feature, error)
	// ListByIDs returns the features with the given IDs, in the order of
	// ids; a missing ID fails with core.ErrNotFound.
	ListByIDs(ctx context.Context, org core.OrganizationID, ids []core.FeatureID) ([]*Feature, error)
	// List returns the organization's features in creation order.
	List(ctx context.Context, org core.OrganizationID, page core.PageRequest) (core.Page[*Feature], error)
}

// EntitlementRepository stores the entitlements of plans and subscriptions
// and the subscriptions' removals. Every method is scoped to an
// organization.
type EntitlementRepository interface {
	// Create inserts e; a second entitlement of the same feature for the
	// same owner fails with core.ErrConflict.
	Create(ctx context.Context, e *Entitlement) error
	// Update replaces the stored entitlement e.ID with e.
	Update(ctx context.Context, e *Entitlement) error
	// Delete removes the entitlement id.
	Delete(ctx context.Context, org core.OrganizationID, id core.EntitlementID) error
	// DeleteByFeature removes every entitlement and removal of the feature
	// and returns how many rows went.
	DeleteByFeature(ctx context.Context, org core.OrganizationID, feature core.FeatureID) (int, error)
	// Get returns the entitlement id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.EntitlementID) (*Entitlement, error)
	// ListByPlan returns the plan's entitlements in creation order.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*Entitlement, error)
	// ListBySubscription returns the subscription's own entitlements in
	// creation order.
	ListBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*Entitlement, error)
	// CreateRemoval inserts r; the same removal twice fails with
	// core.ErrConflict.
	CreateRemoval(ctx context.Context, r *EntitlementRemoval) error
	// DeleteRemoval removes the removal id.
	DeleteRemoval(ctx context.Context, org core.OrganizationID, id core.EntitlementRemovalID) error
	// ListRemovalsBySubscription returns the subscription's removals in
	// creation order.
	ListRemovalsBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*EntitlementRemoval, error)
}
